window.LIB = {"Ab_Crunch_Machine": {"name": "Ab Crunch Machine", "muscles": ["abdominals"], "steps": ["Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position.", "At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs and feet.", "After a second pause, slowly return to the starting position as you breathe in.", "Repeat the movement for the prescribed amount of repetitions."], "frames": 2}, "Barbell_Hip_Thrust": {"name": "Barbell Hip Thrust", "muscles": ["glutes"], "steps": ["Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise.", "Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it.", "Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your feet. Extend as far as possible, then reverse the motion to return to the starting position."], "frames": 2}, "Barbell_Shrug": {"name": "Barbell Shrug", "muscles": ["traps"], "steps": ["Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position.", "Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Bent_Over_Barbell_Row": {"name": "Bent Over Barbell Row", "muscles": ["middle back"], "steps": ["Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows close to the body and only use the forearms to hold the weight. At the top contracted position, squeeze the back muscles and hold for a brief pause.", "Then inhale and slowly lower the barbell back to the starting position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Bent_Over_Two-Dumbbell_Row_With_Palms_In": {"name": "Bent Over Two-Dumbbell Row With Palms In", "muscles": ["middle back"], "steps": ["With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position.", "While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your shoulder blades together. On the top contracted position, squeeze the back muscles and hold for a second.", "Slowly lower the weight again to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Butterfly": {"name": "Butterfly", "muscles": ["chest"], "steps": ["Sit on the machine with your back flat on the pad.", "Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position.", "Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second.", "Return back to the starting position slowly as you inhale until your chest muscles are fully stretched.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Cable_Crossover": {"name": "Cable Crossover", "muscles": ["chest"], "steps": ["To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand.", "Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position.", "With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side (straight out at both sides) in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms and torso should remain stationary; the movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you breathe out. Make sure to use the same arc of motion used to lower the weights.", "Hold for a second at the starting position and repeat the movement for the prescribed amount of repetitions."], "frames": 2}, "Cable_Crunch": {"name": "Cable Crunch", "muscles": ["abdominals"], "steps": ["Kneel below a high pulley that contains a rope attachment.", "Grasp cable rope attachment and lower the rope until your hands are placed next to your face.", "Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position.", "With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second.", "Slowly return to the starting position as you inhale. Tip: Make sure that you keep constant tension on the abs throughout the movement. Also, do not choose a weight so heavy that the lower back handles the brunt of the work.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Cable_Hammer_Curls_-_Rope_Attachment": {"name": "Cable Hammer Curls - Rope Attachment", "muscles": ["biceps"], "steps": ["Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it.", "Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary.", "Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position.", "Using your biceps, pull your arms up as you exhale until your biceps touch your forearms. Tip: Remember to keep the elbows in and your upper arms stationary.", "After a 1 second contraction where you squeeze your biceps, slowly start to bring the weight back to the original position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Cable_Rear_Delt_Fly": {"name": "Cable Rear Delt Fly", "muscles": ["shoulders"], "steps": ["Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head.", "Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position.", "Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement.", "Pause at the end of the motion before returning the handles to the start position."], "frames": 2}, "Cable_Rope_Overhead_Triceps_Extension": {"name": "Cable Rope Overhead Triceps Extension", "muscles": ["triceps"], "steps": ["Attach a rope to the bottom pulley of the pulley machine.", "Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position.", "Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when your triceps are fully stretched.", "Return to the starting position by flexing your triceps as you breathe out.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Cable_Seated_Lateral_Raise": {"name": "Cable Seated Lateral Raise", "muscles": ["shoulders"], "steps": ["Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley.", "Now sit at the edge of the flat bench behind you with your feet placed in front of your knees.", "Bend forward while keeping your back flat and rest your torso on the thighs.", "Have someone give you the single handles attached to the pulleys. Grasp the left pulley with the right hand and the right pulley with the left after you select your weight. The pulleys should run under your knees and your arms will be extended with palms facing each other and a slight bend at the elbows. This will be the starting position.", "While keeping the arms stationary, raise the upper arms to the sides until they are parallel to the floor and at shoulder height. Exhale during the execution of this movement and hold the contraction for a second.", "Slowly lower your arms to the starting position as you inhale.", "Repeat for the recommended amount of repetitions. Tip: Maintain upper arms perpendicular to torso and a fixed elbow position (10 degree to 30 degree angle) throughout exercise."], "frames": 2}, "Dumbbell_Incline_Row": {"name": "Dumbbell Incline Row", "muscles": ["middle back"], "steps": ["Using a neutral grip, lean into an incline bench.", "Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position.", "Retract the shoulder blades and flex the elbows to row the dumbbells to your side.", "Pause at the top of the motion, and then return to the starting position."], "frames": 2}, "Dumbbell_Shrug": {"name": "Dumbbell Shrug", "muscles": ["traps"], "steps": ["Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides.", "Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down.", "Lower the dumbbells back to the original position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "EZ-Bar_Curl": {"name": "EZ-Bar Curl", "muscles": ["biceps"], "steps": ["Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position.", "Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms.", "Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder level. Hold the top contracted position for a moment and squeeze the biceps.", "Then inhale and slowly lower the bar back to the starting position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Face_Pull": {"name": "Face Pull", "muscles": ["shoulders"], "steps": ["Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground."], "frames": 2}, "Hack_Squat": {"name": "Hack Squat", "muscles": ["quadriceps"], "steps": ["Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided.", "Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times.", "Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal position).", "Now straighten your legs without locking the knees. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Begin to slowly lower the unit by bending the knees as you maintain a straight posture with the head up (back on the pad at all times). Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the unit as you exhale by pushing the floor with mainly with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Hammer_Curls": {"name": "Hammer Curls", "muscles": ["biceps"], "steps": ["Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso.", "The palms of the hands should be facing your torso. This will be your starting position.", "Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze the biceps. Tip: Focus on keeping the elbow stationary and only moving your forearm.", "After the brief pause, inhale and slowly begin the lower the dumbbells back down to the starting position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Hammer_Grip_Incline_DB_Bench_Press": {"name": "Hammer Grip Incline DB Bench Press", "muscles": ["chest"], "steps": ["Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other.", "By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width.", "Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creating a 90-degree angle between the upper arm and the forearm. This will be your starting position.", "Now bring down the weights slowly to your side as you breathe in. Keep full control of the dumbbells at all times.", "As you breathe out, push the dumbbells up using your pectoral muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the dumbbells back in your thighs and then on the floor. This is the safest manner to dispose of the dumbbells."], "frames": 2}, "Hanging_Leg_Raise": {"name": "Hanging Leg Raise", "muscles": ["abdominals"], "steps": ["Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position.", "Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so.", "Go back slowly to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Incline_Cable_Flye": {"name": "Incline Cable Flye", "muscles": ["chest"], "steps": ["To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso).", "Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand.", "With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position.", "With a slight bend of your elbows (in order to prevent stress at the biceps tendon), lower your arms out at both sides in a wide arc until you feel a stretch on your chest. Breathe in as you perform this portion of the movement. Tip: Keep in mind that throughout the movement, the arms should remain stationary. The movement should only occur at the shoulder joint.", "Return your arms back to the starting position as you squeeze your chest muscles and exhale. Hold the contracted position for a second. Tip: Make sure to use the same arc of motion used to lower the weights.", "Repeat the movement for the prescribed amount of repetitions."], "frames": 2}, "Incline_Dumbbell_Flyes": {"name": "Incline Dumbbell Flyes", "muscles": ["chest"], "steps": ["Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees.", "Extend your arms above you with a slight bend at the elbows.", "Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position.", "As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing each other. Tip: At the end of the movement the arms will be by your side with the palms facing the ceiling.", "As you exhale start to bring the dumbbells back up to the starting position by reversing the motion and rotating the hands so that the pinky fingers are next to each other again. Tip: Keep in mind that the movement will only happen at the shoulder joint and at the wrist. There is no motion that happens at the elbow joint.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Incline_Dumbbell_Press": {"name": "Incline Dumbbell Press", "muscles": ["chest"], "steps": ["Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other.", "Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width.", "Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position.", "Be sure to keep full control of the dumbbells at all times. Then breathe out and push the dumbbells up with your chest.", "Lock your arms at the top, hold for a second, and then start slowly lowering the weight. Tip Ideally, lowering the weights should take about twice as long as raising them.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the dumbbells back on your thighs and then on the floor. This is the safest manner to release the dumbbells."], "frames": 2}, "Leg_Extensions": {"name": "Leg Extensions", "muscles": ["quadriceps"], "steps": ["For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over the toes which in turn creates undue stress at the knee joint. If the machine is designed that way, either look for another machine or just make sure that when you start executing the exercise you stop going down once you hit the 90-degree angle.", "Using your quadriceps, extend your legs to the maximum as you exhale. Ensure that the rest of the body remains stationary on the seat. Pause a second on the contracted position.", "Slowly lower the weight back to the original position as you inhale, ensuring that you do not go past the 90-degree angle limit.", "Repeat for the recommended amount of times."], "frames": 2}, "Leg_Press": {"name": "Leg Press", "muscles": ["quadriceps"], "steps": ["Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section).", "Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you. Tip: Make sure that you do not lock your knees. Your torso and the legs should make a perfect 90-degree angle. This will be your starting position.", "As you inhale, slowly lower the platform until your upper and lower legs make a 90-degree angle.", "Pushing mainly with the heels of your feet and using the quadriceps go back to the starting position as you exhale.", "Repeat for the recommended amount of repetitions and ensure to lock the safety pins properly once you are done. You do not want that platform falling on you fully loaded."], "frames": 2}, "Leverage_Chest_Press": {"name": "Leverage Chest Press", "muscles": ["chest"], "steps": ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion.", "Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."], "frames": 2}, "Leverage_Incline_Chest_Press": {"name": "Leverage Incline Chest Press", "muscles": ["chest"], "steps": ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position.", "Press the handles forward by extending through the elbow.", "After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."], "frames": 2}, "Leverage_Iso_Row": {"name": "Leverage Iso Row", "muscles": ["lats"], "steps": ["Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position.", "Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow.", "Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles being worked."], "frames": 2}, "Leverage_Shoulder_Press": {"name": "Leverage Shoulder Press", "muscles": ["shoulders"], "steps": ["Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position.", "Press the handles upward by extending through the elbow.", "After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is complete."], "frames": 2}, "Low_Cable_Crossover": {"name": "Low Cable Crossover", "muscles": ["chest"], "steps": ["To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand.", "Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position.", "With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up.", "Return your arms back to the starting position after a brief pause."], "frames": 2}, "Lying_Dumbbell_Tricep_Extension": {"name": "Lying Dumbbell Tricep Extension", "muscles": ["triceps"], "steps": ["Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position.", "As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears.", "At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring the weight back up to the starting position as you breathe out.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Lying_Leg_Curls": {"name": "Lying Leg Curls", "muscles": ["hamstrings"], "steps": ["Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment.", "Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other two stances described on the foot positioning section). This will be your starting position.", "As you exhale, curl your legs up as far as possible without lifting the upper legs from the pad. Once you hit the fully contracted position, hold it for a second.", "As you inhale, bring the legs back to the initial position. Repeat for the recommended amount of repetitions."], "frames": 2}, "Lying_T-Bar_Row": {"name": "Lying T-Bar Row", "muscles": ["middle back"], "steps": ["Load up the T-bar Row Machine with the desired weight and adjust the leg height so that your upper chest is at the top of the pad. Tip: In some machines all you can do is stand on the appropriate step that allows you to be at a height that has the upper chest at the top of the pad.", "Lay face down on the pad and grab the handles. You can either use a palms down, palms up, or palms in position depending on what part of your back you want to emphasize.", "Lift the bar off the rack and extend your arms in front of you. This will be your starting position.", "As you exhale slowly pull the weight up and squeeze your back at the top of the movement. Tip: Keep the upper arms as close to the torso as possible throughout the movement in order to better engage the back muscles. Also, do not lift your body off of the pad at any time and refrain from using the biceps to lift the weight.", "After a second contraction at the top of the movement, as you inhale, slowly go back down to the starting position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Machine_Bench_Press": {"name": "Machine Bench Press", "muscles": ["chest"], "steps": ["Sit down on the Chest Press Machine and select the weight.", "Step on the lever provided by the machine since it will help you to bring the handles forward so that you can grab the handles and fully extend the arms.", "Grab the handles with a palms-down grip and lift your elbows so that your upper arms are parallel to the floor to the sides of your torso. Tip: Your forearms will be pointing forward since you are grabbing the handles. Once you bring the handles forward and extend the arms you will be at the starting position.", "Now bring the handles back towards you as you breathe in.", "Push the handles away from you as you flex your pecs and you breathe out. Hold the contraction for a second before going back to the starting position.", "Repeat for the recommended amount of reps.", "When finished step on the lever again and slowly get the handles back to their original place."], "frames": 2}, "Machine_Preacher_Curls": {"name": "Machine Preacher Curls", "muscles": ["biceps"], "steps": ["Sit down on the Preacher Curl Machine and select the weight.", "Place the back of your upper arms (your triceps) on the preacher pad provided and grab the handles using an underhand grip (palms facing up). Tip: Make sure that when you place the arms on the pad you keep the elbows in. This will be your starting position.", "Now lift the handles as you exhale and you contract the biceps. At the top of the position make sure that you hold the contraction for a second. Tip: Only the forearms should move. The upper arms should remain stationary and on the pad at all times.", "Lower the handles slowly back to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Machine_Shoulder_Military_Press": {"name": "Machine Shoulder (Military) Press", "muscles": ["shoulders"], "steps": ["Sit down on the Shoulder Press Machine and select the weight.", "Grab the handles to your sides as you keep the elbows bent and in line with your torso. This will be your starting position.", "Now lift the handles as you exhale and you extend the arms fully. At the top of the position make sure that you hold the contraction for a second.", "Lower the handles slowly back to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Middle_Back_Shrug": {"name": "Middle Back Shrug", "muscles": ["middle back"], "steps": ["Lie facedown on an incline bench while holding a dumbbell in each hand. Your arms should be fully extended hanging down and pointing towards the floor. The palms of your hands should be facing each other. This will be your starting position.", "As you exhale, squeeze your shoulder blades together and hold the contraction for a full second. Tip: This movement is just like the reverse action of a hug, or trying to perform rear laterals as if you had no arms.", "As you inhale go back to the starting position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "One-Arm_Dumbbell_Row": {"name": "One-Arm Dumbbell Row", "muscles": ["middle back"], "steps": ["Choose a flat bench and place a dumbbell on each side of it.", "Place the right leg on top of the end of the bench, bend your torso forward from the waist until your upper body is parallel to the floor, and place your right hand on the other end of the bench for support.", "Use the left hand to pick up the dumbbell on the floor and hold the weight while keeping your lower back straight. The palm of the hand should be facing your torso. This will be your starting position.", "Pull the resistance straight up to the side of your chest, keeping your upper arm close to your side and keeping the torso stationary. Breathe out as you perform this step. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. Also, make sure that the force is performed with the back muscles and not the arms. Finally, the upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the dumbbell; therefore do not try to pull the dumbbell up using the forearms.", "Lower the resistance straight down to the starting position. Breathe in as you perform this step.", "Repeat the movement for the specified amount of repetitions.", "Switch sides and repeat again with the other arm."], "frames": 2}, "One-Arm_Side_Laterals": {"name": "One-Arm Side Laterals", "muscles": ["shoulders"], "steps": ["Pick a dumbbell and place it in one of your hands. Your non lifting hand should be used to grab something steady such as an incline bench press. Lean towards your lifting arm and away from the hand that is gripping the incline bench as this will allow you to keep your balance.", "Stand with a straight torso and have the dumbbell by your side at arm's length with the palm of the hand facing you. This will be your starting position.", "While maintaining the torso stationary (no swinging), lift the dumbbell to your side with a slight bend on the elbow and your hand slightly tilted forward as if pouring water in a glass. Continue to go up until you arm is parallel to the floor. Exhale as you execute this movement and pause for a second at the top.", "Lower the dumbbell back down slowly to the starting position as you inhale.", "Repeat for the recommended amount of repetitions.", "Switch arms and repeat the exercise."], "frames": 2}, "One_Arm_Dumbbell_Preacher_Curl": {"name": "One Arm Dumbbell Preacher Curl", "muscles": ["biceps"], "steps": ["Grab a dumbbell with the right arm and place the upper arm on top of the preacher bench or the incline bench. The dumbbell should be held at shoulder length. This will be your starting position.", "As you breathe in, slowly lower the dumbbell until your upper arm is extended and the biceps is fully stretched.", "As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the dumbbell is at shoulder height. Again, remember that to ensure full contraction you need to bring that small finger higher than the thumb.", "Squeeze the biceps hard for a second at the contracted position and repeat for the recommended amount of repetitions.", "Switch arms and repeat the movement."], "frames": 2}, "Preacher_Curl": {"name": "Preacher Curl", "muscles": ["biceps"], "steps": ["To perform this movement you will need a preacher bench and an E-Z bar. Grab the E-Z curl bar at the close inner handle (either have someone hand you the bar which is preferable or grab the bar from the front bar rest provided by most preacher benches). The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar.", "With the upper arms positioned against the preacher bench pad and the chest against it, hold the E-Z Curl Bar at shoulder length. This will be your starting position.", "As you breathe in, slowly lower the bar until your upper arm is extended and the biceps is fully stretched.", "As you exhale, use the biceps to curl the weight up until your biceps is fully contracted and the bar is at shoulder height. Squeeze the biceps hard and hold this position for a second.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Reverse_Barbell_Curl": {"name": "Reverse Barbell Curl", "muscles": ["biceps"], "steps": ["Stand up with your torso upright while holding a barbell at shoulder width with the elbows close to the torso. The palm of your hands should be facing down (pronated grip). This will be your starting position.", "While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.", "Slowly begin to bring the bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Reverse_Cable_Curl": {"name": "Reverse Cable Curl", "muscles": ["biceps"], "steps": ["Stand up with your torso upright while holding a bar attachment that is attached to a low pulley using a pronated (palms down) and shoulder width grip. Make sure also that you keep the elbows close to the torso. This will be your starting position.", "While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.", "Slowly begin to bring the bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Reverse_Crunch": {"name": "Reverse Crunch", "muscles": ["abdominals"], "steps": ["Lie down on the floor with your legs fully extended and arms to the side of your torso with the palms on the floor. Your arms should be stationary for the entire exercise.", "Move your legs up so that your thighs are perpendicular to the floor and feet are together and parallel to the floor. This is the starting position.", "While inhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the floor. At the end of this movement your knees will be touching your chest.", "Hold the contraction for a second and move your legs back to the starting position while exhaling.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Reverse_Grip_Triceps_Pushdown": {"name": "Reverse Grip Triceps Pushdown", "muscles": ["triceps"], "steps": ["Start by setting a bar attachment (straight or e-z) on a high pulley machine.", "Facing the bar attachment, grab it with the palms facing up (supinated grip) at shoulder width. Lower the bar by using your lats until your arms are fully extended by your sides. Tip: Elbows should be in by your sides and your feet should be shoulder width apart from each other. This is the starting position.", "Slowly elevate the bar attachment up as you inhale so it is aligned with your chest. Only the forearms should move and the elbows/upper arms should be stationary by your side at all times.", "Then begin to lower the cable bar back down to the original staring position while exhaling and contracting the triceps hard.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Reverse_Machine_Flyes": {"name": "Reverse Machine Flyes", "muscles": ["shoulders"], "steps": ["Adjust the handles so that they are fully to the rear. Make an appropriate weight selection and adjust the seat height so the handles are at shoulder level. Grasp the handles with your hands facing inwards. This will be your starting position.", "In a semicircular motion, pull your hands out to your side and back, contracting your rear delts.", "Keep your arms slightly bent throughout the movement, with all of the motion occurring at the shoulder joint.", "Pause at the rear of the movement, and slowly return the weight to the starting position."], "frames": 2}, "Romanian_Deadlift": {"name": "Romanian Deadlift", "muscles": ["hamstrings"], "steps": ["Put a barbell in front of you on the ground and grab it using a pronated (palms facing down) grip that a little wider than shoulder width. Tip: Depending on the weight used, you may need wrist wraps to perform the exercise and also a raised platform in order to allow for better range of motion.", "Bend the knees slightly and keep the shins vertical, hips back and back straight. This will be your starting position.", "Keeping your back and arms completely straight at all times, use your hips to lift the bar as you exhale. Tip: The movement should not be fast but steady and under control.", "Once you are standing completely straight up, lower the bar by pushing the hips back, only slightly bending the knees, unlike when squatting. Tip: Take a deep breath at the start of the movement and keep your chest up. Hold your breath as you lower and exhale as you complete the movement.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Rope_Straight-Arm_Pulldown": {"name": "Rope Straight-Arm Pulldown", "muscles": ["lats"], "steps": ["Attach a rope to a high pulley and make your weight selection. Stand a couple feet back from the pulley with your feet staggered and take the rope with both hands. Lean forward from the hip, keeping your back straight, with your arms extended up in front of you. This will be your starting position.", "Keeping your arms straight, extend the shoulder to pull the rope down to your thighs.", "Pause at the bottom of the motion, squeezing your lats.", "Return to the starting position without allowing the weight to fully rest on the stack."], "frames": 2}, "Seated_Bent-Over_Rear_Delt_Raise": {"name": "Seated Bent-Over Rear Delt Raise", "muscles": ["shoulders"], "steps": ["Place a couple of dumbbells looking forward in front of a flat bench.", "Sit on the end of the bench with your legs together and the dumbbells behind your calves.", "Bend at the waist while keeping the back straight in order to pick up the dumbbells. The palms of your hands should be facing each other as you pick them. This will be your starting position.", "Keeping your torso forward and stationary, and the arms slightly bent at the elbows, lift the dumbbells straight to the side until both arms are parallel to the floor. Exhale as you lift the weights. (Note: avoid swinging the torso or bringing the arms back as opposed to the side.)", "After a one second contraction at the top, slowly lower the dumbbells back to the starting position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Seated_Cable_Rows": {"name": "Seated Cable Rows", "muscles": ["middle back"], "steps": ["For this exercise you will need access to a low pulley row machine with a V-bar. Note: The V-bar will enable you to have a neutral grip where the palms of your hands face each other. To get into the starting position, first sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked.", "Lean over as you keep the natural alignment of your back and grab the V-bar handles.", "With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should be slightly arched and your chest should be sticking out. You should be feeling a nice stretch on your lats as you hold the bar in front of you. This is the starting position of the exercise.", "Keeping the torso stationary, pull the handles back towards your torso while keeping the arms close to it until you touch the abdominals. Breathe out as you perform that movement. At that point you should be squeezing your back muscles hard. Hold that contraction for a second and slowly go back to the original position while breathing in.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Seated_Leg_Curl": {"name": "Seated Leg Curl", "muscles": ["hamstrings"], "steps": ["Adjust the machine lever to fit your height and sit on the machine with your back against the back support pad.", "Place the back of lower leg on top of padded lever (just a few inches under the calves) and secure the lap pad against your thighs, just above the knees. Then grasp the side handles on the machine as you point your toes straight (or you can also use any of the other two stances) and ensure that the legs are fully straight right in front of you. This will be your starting position.", "As you exhale, pull the machine lever as far as possible to the back of your thighs by flexing at the knees. Keep your torso stationary at all times. Hold the contracted position for a second.", "Slowly return to the starting position as you breathe in.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Seated_Leg_Tucks": {"name": "Seated Leg Tucks", "muscles": ["abdominals"], "steps": ["Sit on a bench with the legs stretched out in front of you slightly below parallel and your arms holding on to the sides of the bench. Your torso should be leaning backwards around a 45-degree angle from the bench. This will be your starting position.", "Bring the knees in toward you as you move your torso closer to them at the same time. Breathe out as you perform this movement.", "After a second pause, go back to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Side_Lateral_Raise": {"name": "Side Lateral Raise", "muscles": ["shoulders"], "steps": ["Pick a couple of dumbbells and stand with a straight torso and the dumbbells by your side at arms length with the palms of the hand facing you. This will be your starting position.", "While maintaining the torso in a stationary position (no swinging), lift the dumbbells to your side with a slight bend on the elbow and the hands slightly tilted forward as if pouring water in a glass. Continue to go up until you arms are parallel to the floor. Exhale as you execute this movement and pause for a second at the top.", "Lower the dumbbells back down slowly to the starting position as you inhale.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Smith_Machine_Close-Grip_Bench_Press": {"name": "Smith Machine Close-Grip Bench Press", "muscles": ["triceps"], "steps": ["Place a flat bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the flat bench. Using a close and pronated grip (palms facing forward) that is around shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that as opposed to a regular bench press, you keep the elbows close to the torso at all times in order to maximize triceps involvement.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your triceps muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, lock the bar back in the rack."], "frames": 2}, "Smith_Machine_Incline_Bench_Press": {"name": "Smith Machine Incline Bench Press", "muscles": ["chest"], "steps": ["Place an incline bench underneath the smith machine. Place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Once the weight you need is selected, lie down on the incline bench and make sure your upper chest is aligned with the barbell. Using a pronated grip (palms facing forward) that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms locked. This will be your starting position.", "As you breathe in, come down slowly until you feel the bar on your upper chest.", "After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms in the contracted position, hold for a second and then start coming down slowly again. Tip: It should take at least twice as long to go down than to come up.", "Repeat the movement for the prescribed amount of repetitions.", "When you are done, place the bar back in the rack."], "frames": 2}, "Smith_Machine_Squat": {"name": "Smith Machine Squat", "muscles": ["quadriceps"], "steps": ["To begin, first set the bar on the height that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it.", "Hold on to the bar using both arms at each side (palms facing forward), unlock it and lift it off the rack by first pushing with your legs and at the same time straightening your torso.", "Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times and also maintain a straight back. This will be your starting position. (Note: For the purposes of this discussion we will use the medium stance which targets overall development; however you can choose any of the three stances discussed in the foot stances section).", "Begin to slowly lower the bar by bending the knees as you maintain a straight posture with the head up. Continue down until the angle between the upper leg and the calves becomes slightly less than 90-degrees (which is the point in which the upper legs are below parallel to the floor). Inhale as you perform this portion of the movement. Tip: If you performed the exercise correctly, the front of the knees should make an imaginary straight line with the toes that is perpendicular to the front. If your knees are past that imaginary line (if they are past your toes) then you are placing undue stress on the knee and the exercise has been performed incorrectly.", "Begin to raise the bar as you exhale by pushing the floor with the heel of your foot as you straighten the legs again and go back to the starting position.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Split_Squat_with_Dumbbells": {"name": "Split Squat with Dumbbells", "muscles": ["quadriceps"], "steps": ["Position yourself into a staggered stance with the rear foot elevated and front foot forward.", "Hold a dumbbell in each hand, letting them hang at the sides. This will be your starting position.", "Begin by descending, flexing your knee and hip to lower your body down. Maintain good posture througout the movement. Keep the front knee in line with the foot as you perform the exercise.", "At the bottom of the movement, drive through the heel to extend the knee and hip to return to the starting position."], "frames": 2}, "Standing_Biceps_Cable_Curl": {"name": "Standing Biceps Cable Curl", "muscles": ["biceps"], "steps": ["Stand up with your torso upright while holding a cable curl bar that is attached to a low pulley. Grab the cable bar at shoulder width and keep the elbows close to the torso. The palm of your hands should be facing up (supinated grip). This will be your starting position.", "While holding the upper arms stationary, curl the weights while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second as you squeeze the muscle.", "Slowly begin to bring the curl bar back to starting position as your breathe in.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Standing_Cable_Wood_Chop": {"name": "Standing Cable Wood Chop", "muscles": ["abdominals"], "steps": ["Connect a standard handle to a tower, and move the cable to the highest pulley position.", "With your side to the cable, grab the handle with one hand and step away from the tower. You should be approximately arm's length away from the pulley, with the tension of the weight on the cable. Your outstretched arm should be aligned with the cable.", "With your feet positioned shoulder width apart, reach upward with your other hand and grab the handle with both hands. Your arms should still be fully extended.", "In one motion, pull the handle down and across your body to your front knee while rotating your torso.", "Keep your back and arms straight and core tight while you pivot your back foot and bend your knees to get a full range of motion.", "Maintain your stance and straight arms. Return to the neutral position in a slow and controlled manner.", "Repeat to failure.", "Then, reposition and repeat the same series of movements on the opposite side."], "frames": 2}, "Standing_Dumbbell_Triceps_Extension": {"name": "Standing Dumbbell Triceps Extension", "muscles": ["triceps"], "steps": ["To begin, stand up with a dumbbell held by both hands. Your feet should be about shoulder width apart from each other. Slowly use both hands to grab the dumbbell and lift it over your head until both arms are fully extended.", "The resistance should be resting in the palms of your hands with your thumbs around it. The palm of the hands should be facing up towards the ceiling. This will be your starting position.", "Keeping your upper arms close to your head with elbows in and perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.", "Go back to the starting position by using the triceps to raise the dumbbell. Breathe out as you perform this step.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Standing_Overhead_Barbell_Triceps_Extension": {"name": "Standing Overhead Barbell Triceps Extension", "muscles": ["triceps"], "steps": ["To begin, stand up holding a barbell or e-z bar using a pronated grip (palms facing forward) with your hands closer than shoulder width apart from each other. Your feet should be about shoulder width apart.", "Now elevate the barbell above your head until your arms are fully extended. Keep your elbows in. This will be your starting position.", "Keeping your upper arms close to your head and elbows in, perpendicular to the floor, lower the resistance in a semicircular motion behind your head until your forearms touch your biceps. Tip: The upper arms should remain stationary and only the forearms should move. Breathe in as you perform this step.", "Go back to the starting position by using the triceps to raise the barbell. Breathe out as you perform this step.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Stiff-Legged_Dumbbell_Deadlift": {"name": "Stiff-Legged Dumbbell Deadlift", "muscles": ["hamstrings"], "steps": ["Grasp a couple of dumbbells holding them by your side at arm's length.", "Stand with your torso straight and your legs spaced using a shoulder width or narrower stance. The knees should be slightly bent. This is your starting position.", "Keeping the knees stationary, lower the dumbbells to over the top of your feet by bending at the waist while keeping your back straight. Keep moving forward as if you were going to pick something from the floor until you feel a stretch on the hamstrings. Exhale as you perform this movement", "Start bringing your torso up straight again by extending your hips and waist until you are back at the starting position. Inhale as you perform this movement.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Straight-Arm_Pulldown": {"name": "Straight-Arm Pulldown", "muscles": ["lats"], "steps": ["You will start by grabbing the wide bar from the top pulley of a pulldown machine and using a wider than shoulder-width pronated (palms down) grip. Step backwards two feet or so.", "Bend your torso forward at the waist by around 30-degrees with your arms fully extended in front of you and a slight bend at the elbows. If your arms are not fully extended then you need to step a bit more backwards until they are. Once your arms are fully extended and your torso is slightly bent at the waist, tighten the lats and then you are ready to begin.", "While keeping the arms straight, pull the bar down by contracting the lats until your hands are next to the side of the thighs. Breathe out as you perform this step.", "While keeping the arms straight, go back to the starting position while breathing in.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Thigh_Abductor": {"name": "Thigh Abductor", "muscles": ["abductors"], "steps": ["To begin, sit down on the abductor machine and select a weight you are comfortable with. When your legs are positioned properly, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.", "Slowly press against the machine with your legs to move them away from each other while exhaling.", "Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary to prevent any injuries from occurring.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Thigh_Adductor": {"name": "Thigh Adductor", "muscles": ["adductors"], "steps": ["To begin, sit down on the adductor machine and select a weight you are comfortable with. When your legs are positioned properly on the leg pads of the machine, grip the handles on each side. Your entire upper body (from the waist up) should be stationary. This is the starting position.", "Slowly press against the machine with your legs to move them towards each other while exhaling.", "Feel the contraction for a second and begin to move your legs back to the starting position while breathing in. Note: Remember to keep your upper body stationary and avoid fast jerking motions in order to prevent any injuries from occurring.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Triceps_Overhead_Extension_with_Rope": {"name": "Triceps Overhead Extension with Rope", "muscles": ["triceps"], "steps": ["Attach a rope to a low pulley. After selecting an appropriate weight, grasp the rope with both hands and face away from the cable.", "Position your hands behind your head with your elbows point straight up. Your elbows should start out flexed, and you can stagger your stance and lean gently away from the machine to create greater stability. This will be your starting position.", "To perform the movement, extend through the elbow while keeping the upper arm in position, raising your hands above your head.", "Squeeze your triceps at the top of the movement, and slowly lower the weight back to the start position."], "frames": 2}, "Triceps_Pushdown": {"name": "Triceps Pushdown", "muscles": ["triceps"], "steps": ["Attach a straight or angled bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. This is your starting position.", "Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After a second hold at the contracted position, bring the bar slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Triceps_Pushdown_-_Rope_Attachment": {"name": "Triceps Pushdown - Rope Attachment", "muscles": ["triceps"], "steps": ["Attach a rope attachment to a high pulley and grab with a neutral grip (palms facing each other).", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the rope with the palms facing each other. This is your starting position.", "Using the triceps, bring the rope down as you bring each side of the rope to the side of your thighs. At the end of the movement the arms are fully extended and perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After holding for a second, at the contracted position, bring the rope slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Triceps_Pushdown_-_V-Bar_Attachment": {"name": "Triceps Pushdown - V-Bar Attachment", "muscles": ["triceps"], "steps": ["Attach a V-Bar to a high pulley and grab with an overhand grip (palms facing down) at shoulder width.", "Standing upright with the torso straight and a very small inclination forward, bring the upper arms close to your body and perpendicular to the floor. The forearms should be pointing up towards the pulley as they hold the bar. The thumbs should be higher than the small finger. This is your starting position.", "Using the triceps, bring the bar down until it touches the front of your thighs and the arms are fully extended perpendicular to the floor. The upper arms should always remain stationary next to your torso and only the forearms should move. Exhale as you perform this movement.", "After a second hold at the contracted position, bring the V-Bar slowly up to the starting point. Breathe in as you perform this step.", "Repeat for the recommended amount of repetitions."], "frames": 2}, "Underhand_Cable_Pulldowns": {"name": "Underhand Cable Pulldowns", "muscles": ["lats"], "steps": ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the pull-down bar with the palms facing your torso (a supinated grip). Make sure that the hands are placed closer than the shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, pull the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the fully contracted position and keep the elbows close to your body. The upper torso should remain stationary as your bring the bar to you and only the arms should move. The forearms should do no other work other than hold the bar.", "After a second on the contracted position, while breathing in, slowly bring the bar back to the starting position when your arms are fully extended and the lats are fully stretched.", "Repeat this motion for the prescribed amount of repetitions."], "frames": 2}, "V-Bar_Pulldown": {"name": "V-Bar Pulldown", "muscles": ["lats"], "steps": ["Sit down on a pull-down machine with a V-Bar attached to the top pulley.", "Adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the V-bar with the palms facing each other (a neutral grip). Stick your chest out and lean yourself back slightly (around 30-degrees) in order to better engage the lats. This will be your starting position.", "Using your lats, pull the bar down as you squeeze your shoulder blades. Continue until your chest nearly touches the V-bar. Exhale as you execute this motion. Tip: Keep the torso stationary throughout the movement.", "After a second hold on the contracted position, slowly bring the bar back to the starting position as you breathe in.", "Repeat for the prescribed number of repetitions."], "frames": 2}, "Wide-Grip_Lat_Pulldown": {"name": "Wide-Grip Lat Pulldown", "muscles": ["lats"], "steps": ["Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar.", "Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to your shoulder width and for a close grip at a distance smaller than your shoulder width.", "As you have both arms extended in front of you holding the bar at the chosen grip width, bring your torso back around 30 degrees or so while creating a curvature on your lower back and sticking your chest out. This is your starting position.", "As you breathe out, bring the bar down until it touches your upper chest by drawing the shoulders and the upper arms down and back. Tip: Concentrate on squeezing the back muscles once you reach the full contracted position. The upper torso should remain stationary and only the arms should move. The forearms should do no other work except for holding the bar; therefore do not try to pull down the bar using the forearms.", "After a second at the contracted position squeezing your shoulder blades together, slowly raise the bar back to the starting position when your arms are fully extended and the lats are fully stretched. Inhale during this portion of the movement.", "Repeat this motion for the prescribed amount of repetitions."], "frames": 2}};
